let language = 'bn';
try { language = localStorage.getItem('hudalipi.language') || 'bn'; } catch { /* Use Bengali when storage is unavailable. */ }
function applyLanguage(next) {
  language = next === 'en' ? 'en' : 'bn';
  document.documentElement.lang = language;
  document.documentElement.dataset.language = language;
  document.title = language === 'bn' ? 'Hudalipi — আলোর পথে, জ্ঞানের সাথে' : 'Hudalipi — Words That Guide';
  document.querySelector('meta[name=description]').content = language === 'bn' ? 'হুদালিপি — সহজ বাংলায় ইসলামিক শিক্ষা, দৈনন্দিন দোয়া, সুন্দর আখলাক ও সিরাত থেকে শেখার একটি পথচলা।' : 'Hudalipi shares accessible Islamic learning, everyday duas, good character, and lessons from the Seerah.';
  for (const [key, selector] of Object.entries(selectors)) {
    const node = document.querySelector(selector);
    if (node && copy[language][key]) node.innerHTML = copy[language][key];
  }
  document.querySelector('.prewatch-brand small').textContent = copy[language].brandTagline;
  document.querySelector('.brand').setAttribute('aria-label', language === 'en' ? 'Hudalipi home' : 'Hudalipi হোম');
  document.querySelector('.video-filters').setAttribute('aria-label', language === 'en' ? 'Video type' : 'ভিডিওর ধরন');
  document.querySelector('.topic-grid').setAttribute('aria-label', language === 'en' ? 'Choose a learning topic' : 'শেখার বিষয় বাছাই');
  document.querySelector('.social-actions').setAttribute('aria-label', language === 'en' ? 'Hudalipi social media' : 'Hudalipi-এর সামাজিক মাধ্যম');
  document.querySelectorAll('[data-i18n-aria]').forEach(node => { node.setAttribute('aria-label', copy[language][node.dataset.i18nAria === 'menuOpen' ? (node.getAttribute('aria-expanded') === 'true' ? 'menuClose' : 'menuOpen') : node.dataset.i18nAria]); });
  const toggle = document.querySelector('.language-toggle');
  toggle.textContent = language === 'bn' ? 'English' : 'বাংলা';
  toggle.setAttribute('aria-pressed', String(language === 'en'));
  toggle.setAttribute('aria-label', language === 'bn' ? 'Switch language to English' : 'ভাষা বাংলায় পরিবর্তন করুন');
  const topicCopy = language === 'en' ? {dua:['Learn duas and understand their meaning','We plan to explore everyday duas through their Arabic text, Bengali meaning, and when to recite them. We give care to pronunciation and checking sources.'],quran:['Lessons from verses, reflections for life','We plan to discuss the meaning of Quranic verses in light of recognized tafsir, helping connect their lessons with everyday life.'],adab:['Begin with thoughtful conduct','This topic explores kindness to family, neighbors, and community, thoughtful speech, and responsible living. We hope to build good habits together.'],seerah:['Learn from an exemplary life','We plan to share lessons in honesty, compassion, patience, and good character from reliable accounts of the Prophet’s ﷺ life, with care for sources.']} : {dua:['দোয়া শিখি, অর্থ বুঝি','দৈনন্দিন জীবনের দোয়াগুলো আরবি পাঠ, বাংলা অর্থ এবং কখন পড়তে হয়—এই তিনটি দিক মিলিয়ে শেখার পরিকল্পনা। উচ্চারণ ও সূত্র যাচাইকে আমরা গুরুত্ব দিই।'],quran:['আয়াতের শিক্ষা, জীবনের ভাবনা','কুরআনের আয়াতের অর্থ ও স্বীকৃত তাফসিরের আলোকে সহজ আলোচনা আমাদের পরিকল্পনার অংশ। উদ্দেশ্য—শিক্ষাগুলো বুঝতে এবং দৈনন্দিন জীবনের সঙ্গে মিলিয়ে ভাবতে সাহায্য করা।'],adab:['সুন্দর ব্যবহার থেকেই শুরু','পরিবার, প্রতিবেশী ও সমাজের মানুষের সঙ্গে ভালো আচরণ, কথায় সংযম এবং দায়িত্বশীল জীবনযাপন—এই বিভাগের আলোচনার বিষয়। ছোট ছোট ভালো অভ্যাস গড়তে চাই একসাথে।'],seerah:['আদর্শ জীবন থেকে শেখা','নবীজি ﷺ-এর জীবনের নির্ভরযোগ্য বর্ণনা থেকে সততা, দয়া, ধৈর্য ও সুন্দর আচরণের শিক্ষা তুলে ধরার পরিকল্পনা। ঘটনা ও তার সূত্র যাচাইকে এখানে বিশেষ গুরুত্ব দেওয়া হবে.']};
  const activeTopic = document.querySelector('.topic.active')?.dataset.topic || 'dua';
  if (document.getElementById('topic-title')) { document.getElementById('topic-title').textContent = topicCopy[activeTopic][0]; document.getElementById('topic-description').textContent = topicCopy[activeTopic][1]; }
  document.dispatchEvent(new CustomEvent('hudalipi:language', {detail:{language}}));
}
document.querySelector('.language-toggle').addEventListener('click', () => {
  const next = language === 'bn' ? 'en' : 'bn';
  try { localStorage.setItem('hudalipi.language', next); } catch { /* Keep language switching available when storage is blocked. */ }
  applyLanguage(next);
});
applyLanguage(language);
